window.docContents[174].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Case-Analysis--New-Tactics___--rewrite-_________-at--and--exact":{"contents":"\n\n\n\nYou will need the rewrite ... at and exact tactics to complete some exercises.\n\n\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Proof by Case Analysis","header":"2.5.1. New Tactics:  rewrite ... at  and  exact","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Case-Analysis--New-Tactics___--rewrite-_________-at--and--exact"},"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--The--rewrite--tactic":{"contents":"\n\n\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Proof by Rewriting","header":"2.4.3. The  rewrite  tactic","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--The--rewrite--tactic"},"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Append":{"contents":"\n\ndef append (l₁ l₂ : NatList) : NatList :=\n  match l₁ with\n  | [] => l₂\n  | h :: t => h :: append t l₂\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers","header":"5.3.2. Append","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Append"}});